import React from "react";
import './end.css';

interface EndScreenProps {
    Win: boolean;
    Lose: boolean;
}

const End: React.FC<EndScreenProps> = ({ Win, Lose }) => {
    return(
        <>
            <div className="endcontainer">
                {Win && <div className="wincontainer">You Won!
                <button className="playagain">Play Again?</button>    
                </div>}
                {Lose && <div className="losecontainer">You Lost!</div>}
            </div>
        </>
    );
}

export default End;
